const sourceEffect = thisItem.effects.getName("勇武");
if (sourceEffect) {
    const effData = sourceEffect.toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effData);
}

const sourceEffect = thisItem.effects.getName("尽忠");
