if (args.actionType && !['attack', 'basic-attack'].includes(args.actionType)) return;
const sourceEffect = thisItem.effects.getName("神机");
if (sourceEffect) {
    const effData = sourceEffect.toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    // 圆满特效增加距离暂无法通过AE修改，此处仅处理伤害
    await game.xjzl.api.effects.addEffect(actor, effData);
}

actor._pendingMoraleDelta = (actor._pendingMoraleDelta || 0) + 5;
if (!actor._moraleTimer) {
    actor._moraleTimer = setTimeout(async () => {
        const totalDelta = actor._pendingMoraleDelta;
        actor._pendingMoraleDelta = 0;
        actor._moraleTimer = null;
        const cur = actor.system.resources.morale?.value || 0;
        const newVal = Math.min(100, cur + totalDelta);
        if (newVal !== cur) {
            await actor.changeResources({'system.resources.morale.value': newVal}, { cause: "script", source: "script", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
            actor.showFloatyText(`士气 +${totalDelta}`, {fill: "#00ff00"});
        }
    }, 50);
}
await ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card"><div style="padding:5px;font-weight:bold; color:#d35400; border-bottom:1px solid #ccc; padding-bottom:3px;"><i class="fas fa-flag"></i> 将星录 - 军心大振</div><div style="font-size:0.9em; margin-top:5px;">你的回合开始，所有友方士气 <b style="color:green;">+5</b>！<br><span style="color:#888;">(自身已自动增加，请提醒队友手动增加)</span></div></div>` });

